  function v6Fields(src, dst, type, target) {
    var out = [field("IPv6", "Границы локального обмена", [["Источник → назначение", src + " → " + dst, "Multicast ff02::… относится к этому звену, а не к всемирной рассылке."], ["Hop Limit", "255", "Проверяемое условие сообщений ND; не доказательство личности отправителя."]]), field("ICMPv6 / ND", "Назначение сообщения", [["Тип", type, "ND (Neighbor Discovery) — семейство сообщений для поиска соседей и маршрутизаторов."]])];
    if (target) out[1].items.push(["Target Address", target, "Адрес, о котором спрашиваем; не обязательно IPv6-назначение внешнего пакета."]);
    return out;
  }
